  input [31:0] cache_data_out;
  input [13:0] cpu_addr;
  input [31:0] data_bus_in;
  output [31:0] data_bus_out;
  output [13:0] lookup_addr;
  output [31:0] cpu_data_in;
  input [511:0] line_bus_in;
  output [511:0] line_bus_out;
