module cpu_lite ( clk_cpu, clk_mem, rst, program_memory_data, 
        program_memory_addr );
  input [31:0] program_memory_data;
  output [11:0] program_memory_addr;
  input clk_cpu, clk_mem, rst;
  wire   reset_in, rst_mem, cache_done, cache_start, \rdc/sync1 , n2;
  wire   [1:0] cache_control;
  wire   [13:0] cache_addr;
  wire   [31:0] cache_data_bus;
  wire   [31:0] cache_data_in;

  cpu_core cpu ( .clk_cpu(clk_cpu), .rst(rst), .program_memory_data(
        program_memory_data), .program_memory_addr(program_memory_addr), 
        .cache_done(cache_done), .cache_start(cache_start), .cache_control(
        cache_control), .cache_addr(cache_addr), .cache_data_bus(
        cache_data_bus), .cache_data_in(cache_data_in) );
  memory_interface memory_module ( .clk_cpu(clk_cpu), .clk_mem(clk_mem), .rst(
        rst), .start(cache_start), .rst_sync(n2), .cpu_done(cache_done), 
        .control_signals(cache_control), .cpu_addr(cache_addr), .data_bus_in(
        cache_data_bus), .data_bus_out(cache_data_in) );
  DFFARX1_LVT reset_in_reg ( .D(1'b1), .CLK(clk_cpu), .RSTB(rst), .Q(reset_in)
         );
  DFFARX1_LVT \rdc/sync1_reg  ( .D(reset_in), .CLK(clk_mem), .RSTB(rst), .Q(
        \rdc/sync1 ) );
  DFFARX1_LVT \rdc/sync2_reg  ( .D(\rdc/sync1 ), .CLK(clk_mem), .RSTB(rst), 
        .Q(rst_mem) );
  NBUFFX8_LVT U4 ( .A(rst_mem), .Y(n2) );
endmodule

